{

    									"title": "Historia de Usuario (HU) sobre la reserva de ejemplares en la Biblioteca Municipal de Villaficticia",
    "role": "persona socia",
    "action": "reservar un ejemplar desde la web para recogerlo en el mostrador",
    "benefit": "tener un ejemplar disponible para recoger",
    "description": "La persona socia quiere realizar una reserva de un ejemplar mediante el portal web, asegurando que el mismo esté disponible para recogida en la sede de recogida.",
    "business_goal": "Implementar un proceso de reserva web que cumpla con los reglamentos y garantice la disponibilidad de ejemplares según las normas establecidas.",
    "scope_includes": [
        "Proceso de reserva desde el portal web",
        "Bloqueo de 48 horas para reservas no recogidas",
        "Notificación de caducidad"
    ],
    "scope_excludes": [
        "Prestamos en línea",
        "Reservas remotas",
        "Acceso a la web por parte del personal"
    ],
    "acceptance_criteria": [
        {
            "id": "CA-01",
            "title": "Solicitud válida",
            "given": [
                "La persona socia inicio sesión y seleccionó el título del ejemplar."
            ],
            "when": [
                "Antes de realizar la reserva, se verifica el estado de su cuenta y la validez de su carnet."
            ],
            "then": [
                "Se generan las reservas activas según el Reglamento de reservas."
            ]
        },
        {
            "id": "CA-02",
            "title": "Bloqueo de 48 horas",
            "given": [
                "La reserva no fue recogida dentro de los 48 horas posteriores a su creación."
            ],
            "when": [
                "Después de la fecha de creación de la reserva, y antes de la notificación del caduca."
            ],
            "then": [
                "El ejemplar pasa a estar en cola de recogida y se le notifica al usuario."
            ]
        },
        {
            "id": "CA-03",
            "title": "Cancelación de reserva",
            "given": [
                "La persona socia canceló la reserva antes de recogerla."
            ],
            "when": [
                "Antes de la recogida de la reserva."
            ],
            "then": [
                "La reserva se anula y se elimina del sistema."
            ]
        }
    ],
    "business_rules": [
        {
            "id": "RN-RES-01",
            "description": "Solo se pueden reservar personas socias con carné vigente y sin sanción activa."
        },
        {
            "id": "RN-RES-02",
            "description": "Cada persona socia puede tener máximo 3 reservas activas (pendiente o disponible para recoger)."
        },
        {
            "id": "RN-RES-03",
            "description": "Se asigna el primer ejemplar disponible de un título en la sede de recogida."
        },
        {
            "id": "RN-RES-04",
            "description": "Las reservas de un título se atienden por orden de llegada en una cola de reservas."
        },
        {
            "id": "RN-RES-05",
            "description": "Se bloquea el ejemplar durante 48 horas si está en la sede de recogida."
        },
        {
            "id": "RN-RES-06",
            "description": "Si no se recoge en 48 horas, la reserva caduca y se pone en cola de recogida."
        },
        {
            "id": "RN-RES-07",
            "description": "Se permite cancelar una reserva en cualquier momento antes de recogerla."
        },
        {
            "id": "RN-RES-08",
            "description": "No pueden renovarse las reservas en un título si hay una reserva pendiente en ese título."
        },
        {
            "id": "RN-RES-09",
            "description": "No se pueden reservar obras de referencia o títulos ya en préstamo."
        },
        {
            "id": "RN-RES-10",
            "description": "Las personas con carné infantil pueden reservar solo títulos de la colección infantil y juvenil."
        }
    ],
    "assumptions": [
        "La persona socia tiene un carnet válido y una cuenta activa en el portal web.",
        "El sistema del portal web puede procesar las reservas de forma segura y correctamente.",
        "El sistema de notificaciones puede informar sobre la caducidad de las reservas."
    ],
    "constraints": [
        "El número máximo de reservas activas se ajusta a los reglamentos.",
        "Las reservas no recogidas se acumulan en una cola de espera.",
        "El sistema no permite renovaciones en títulos con reservas pendientes."
    ],
    "dependencies": [
        "El sistema de autenticación",
        "El sistema de notificaciones",
        "El sistema de gestión de reservas"
    ],
    "alternate_flows": [
        "Si el usuario cancela la reserva antes de recogerla, se anula la reserva.",
        "Si el usuario no recoge la reserva en 48 horas, se pone en cola de recogida.",
        "Si la persona socia no tiene un carnet válido, el proceso se bloquea."
    ],
    "exceptions": [
        "Las reservas no recogidas se acumulan en una cola de espera.",
        "El sistema no permite renovaciones en títulos con reservas pendientes."
    ],
    "related_features": [
        "Prestamos en línea",
        "Reservas remotas"
    ],
    "priority": "Should",
    "open_questions": [
        "¿Cuál es el número máximo de reservas activas que se permite por título?",
        "¿Qué tipo de notificaciones se envían a la persona socia sobre la caducidad de una reserva?",
        "¿Se pueden realizar reservas de títulos ya en préstamo?"
    ]
}

